    ld.global.f32 %f4, [%rd16];
    add.f32 %f1, %f1, %f4;

STORE:
    mul.wide.s32 %rd17, %r23, 4;
    add.s64 %rd18, %rd4, %rd17;
    st.global.f32 [%rd18], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, Hin, Win = x.shape
        C_out = self.out_channels
        K = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation
        groups = self.groups

        Hout = (Hin + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1

        y = torch.empty((N, C_out, Hout, Wout), device=x.device, dtype=x.dtype)

        weight = self.conv2d.weight

        if self.has_bias:
            bias = self.conv2d.bias
        else:
            bias = torch.empty(1, device=x.device, dtype=x.dtype)

        total_elements = N * C_out * Hout * Wout

        module = _get_ptx_module()

        threads = 256
        blocks = (total_elements + threads - 1) // threads

        module.launch(
            "conv2d_kernel",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[
                x, weight, bias, y,
                i32(N), i32(C_in), i32(Hin), i32(Win),
                i32(C_out), i32(K),
                i32(stride), i32(padding), i32(dilation), i32(groups),
                i32(Hout), i32(Wout),
                i32(1 if self.has_bias else 0),
                i32(total_elements),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
